class PayrollTaxDocumentViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = TaxDocumentSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return TaxDocument.objects.filter(employee=self.request.user)

    @action(detail=True, methods=['get'], url_path='download')
    def download_tax_form(self, request, pk=None):
        doc = self.get_object()
        return FileResponse(doc.pdf_file.open('rb'), content_type='application/pdf')
